*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101a20;color:#fff;font-family:'DM Sans',sans-serif}body{display:grid;place-items:center}#game-shell{position:relative;width:min(100vw,calc(100vh * 16 / 9));height:min(100vh,calc(100vw * 9 / 16));min-height:320px;overflow:hidden;background:#233b3d;isolation:isolate}canvas{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 53%,transparent 42%,rgba(9,17,21,.16) 100%);z-index:1}.topbar{position:absolute;top:0;left:0;right:0;height:68px;display:flex;align-items:center;padding:0 38px;border-bottom:1px solid rgba(255,255,255,.12);background:linear-gradient(180deg,rgba(13,25,29,.68),transparent);z-index:2}.brand{display:flex;align-items:center;gap:11px;text-decoration:none;color:#f8eaca;font-family:Cinzel,serif;font-size:12px;letter-spacing:2px;font-weight:700}.brand-mark{font-size:23px;color:#edc77d}.brand-light{font-weight:500;color:#d4d0be}.chapter{position:absolute;left:50%;transform:translateX(-50%);font-size:9px;letter-spacing:2px;color:#e0d7be;font-weight:700}.chapter i{font-style:normal;color:#e4bb70;padding:0 8px}.sound{margin-left:auto;background:none;border:0;color:#eadbb9;font:700 10px 'DM Sans';letter-spacing:1.2px;cursor:pointer}.sound span{margin-left:7px}.hud{position:absolute;z-index:2;top:86px;left:38px;display:flex;gap:12px;align-items:flex-start}.hero-card,.objective{height:74px;background:rgba(15,27,29,.79);border:1px solid rgba(239,219,174,.22);backdrop-filter:blur(8px);box-shadow:0 7px 25px #0e1a1b40}.hero-card{width:218px;padding:12px;display:flex;gap:11px;align-items:center}.hero-icon{width:42px;height:42px;border:1px solid #d5ad68;border-radius:50%;display:grid;place-items:center;color:#e8c27d;font-family:serif;font-size:21px;background:radial-gradient(circle,#715437,#262b27 75%)}.hero-info{flex:1;min-width:0}.eyebrow{display:block;color:#d4b87e;font-size:8px;letter-spacing:1.8px;font-weight:700}.hero-info strong{display:block;font:600 14px Cinzel,serif;margin:3px 0 7px;color:#fff6e2}.health-track{height:4px;background:#58423b;border-radius:8px;overflow:hidden}.health-track span{height:100%;display:block;width:100%;background:linear-gradient(90deg,#d7654c,#edb264);transition:width .2s}.hp-count{align-self:flex-end;font-size:10px;color:#e5cda0;margin:0 0 2px}.objective{width:207px;padding:11px 13px}.objective-top{display:flex;justify-content:space-between}.seal-icon{color:#eccb88;font-size:15px;line-height:10px}.quest-text{font:500 11px Cinzel,serif;color:#f4ead1;margin:4px 0 7px}.peach-track{display:flex;gap:6px}.peach-slot{width:14px;height:5px;border-radius:4px;background:#ffffff28;border:1px solid #fff2}.peach-slot.filled{background:#e6b968;border-color:#f7d99a;box-shadow:0 0 8px #f4bb61}.boss-bar{position:absolute;top:89px;left:50%;transform:translateX(-50%);width:260px;z-index:2;opacity:0;transition:opacity .5s;pointer-events:none}.boss-bar.show{opacity:1}.boss-name{display:flex;justify-content:space-between;font-size:9px;font-weight:700;letter-spacing:1.7px;color:#f4d8ac;margin-bottom:6px;text-shadow:0 2px 6px #000}.boss-track{height:5px;background:#2c1618;border:1px solid #d2846a55}.boss-track i{height:100%;width:100%;display:block;background:linear-gradient(90deg,#c74442,#f29666);transition:width .18s}.hint{position:absolute;z-index:2;bottom:22px;left:50%;transform:translateX(-50%);white-space:nowrap;color:#f1e8d1;background:#172522b8;border:1px solid #fff2;padding:9px 16px;font-size:9px;font-weight:700;letter-spacing:1.5px;border-radius:3px;transition:opacity .4s}.hint-key{color:#e7c780;border:1px solid #e8d39b66;padding:3px 5px;margin:0 4px;font-size:8px}.hint-dot{color:#b48e57;margin:0 6px}.screen{position:absolute;inset:0;z-index:5;display:grid;place-items:center;text-align:center;background:linear-gradient(90deg,rgba(10,20,23,.82),rgba(10,20,23,.34) 60%,rgba(10,20,23,.12)),linear-gradient(0deg,#101a20b0,transparent 58%);transition:opacity .7s,visibility .7s}.screen.hidden{opacity:0;visibility:hidden;pointer-events:none}.screen-glow{position:absolute;left:17%;top:9%;height:75%;width:40%;background:radial-gradient(ellipse,rgba(209,154,80,.11),transparent 70%);pointer-events:none}.screen-content{position:relative;z-index:1;width:min(460px,90%);margin-right:auto;margin-left:10%;animation:rise .8s both}.sun-seal{width:43px;height:43px;border:1px solid #d8b671;border-radius:50%;margin:0 auto 15px;display:grid;place-items:center;color:#ebc77e;font-size:24px;box-shadow:0 0 35px #ebc77e35}.screen-content>.eyebrow{font-size:9px;letter-spacing:3.3px}.screen h1,.screen h2{margin:9px 0 2px;font:700 clamp(46px,6.1vw,76px)/.93 Cinzel,serif;letter-spacing:5px;color:#f8f0da;text-shadow:0 4px 24px #0008}.screen h1 span,.screen h2 span{color:#e5bf76}.screen-subtitle{margin:12px 0;color:#e4d7bc;font:500 11px Cinzel,serif;letter-spacing:4px}.screen-rule{display:flex;gap:10px;justify-content:center;align-items:center;color:#deb978;font-size:10px;margin:17px auto}.screen-rule i{width:47px;height:1px;background:linear-gradient(90deg,transparent,#d9b677)}.screen-rule i:last-child{transform:rotate(180deg)}.screen-copy{font-size:12px;line-height:1.9;color:#dbd4c3;margin:17px 0 21px}.primary-btn{height:46px;padding:0 24px;background:#d9b36f;color:#1c211d;border:1px solid #f0d496;font:700 10px 'DM Sans';letter-spacing:1.5px;cursor:pointer;box-shadow:0 5px 25px #dfb86c32;transition:background .2s,transform .2s}.primary-btn:hover{background:#f0d293;transform:translateY(-2px)}.primary-btn span{font-size:17px;margin-left:15px;vertical-align:-1px}.screen-controls{font-size:8px;color:#b9b6a8;letter-spacing:1.3px;margin-top:22px}.screen-controls b{color:#ebd19c}.screen-footer{position:absolute;bottom:20px;left:0;right:0;color:#dbd1b363;font-size:8px;letter-spacing:2.5px}.mobile-controls{display:none}.toast{position:absolute;z-index:3;top:27%;left:50%;transform:translate(-50%,-12px);background:#15221ee8;border:1px solid #dfbe7c77;padding:10px 19px;color:#f3d695;font:500 12px Cinzel,serif;opacity:0;transition:.3s;pointer-events:none;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}@keyframes rise{from{opacity:0;transform:translateY(15px)}to{opacity:1;transform:translateY(0)}}
@media(max-width:700px){#game-shell{width:100vw;height:100dvh;min-height:0}.topbar{height:51px;padding:0 16px}.brand{font-size:10px;gap:7px}.brand-mark{font-size:19px}.chapter{font-size:7px;letter-spacing:1px;left:57%}.sound{font-size:0}.sound span{font-size:8px}.hud{top:62px;left:12px;gap:6px}.hero-card{width:166px;height:61px;padding:8px;gap:7px}.hero-icon{width:35px;height:35px;font-size:17px}.hero-info strong{font-size:11px;margin:2px 0 5px}.eyebrow{font-size:7px;letter-spacing:1.2px}.objective{width:150px;height:61px;padding:8px}.quest-text{font-size:9px;margin:3px 0 6px}.peach-track{gap:4px}.peach-slot{width:12px}.boss-bar{top:132px;width:210px}.hint{display:none}.mobile-controls{display:block;position:absolute;inset:0;z-index:3;pointer-events:none}.dpad{position:absolute;left:17px;bottom:24px;width:132px;height:132px;pointer-events:auto}.dpad button,.action{position:absolute;border:1px solid #e9d39b5c;background:#14211e9c;color:#f2deb4;touch-action:none;backdrop-filter:blur(5px);user-select:none;-webkit-user-select:none}.dpad button{width:43px;height:43px;border-radius:10px;font-size:20px}.dpad .up{left:44px;top:0}.dpad .left{left:0;top:44px}.dpad .down{left:44px;top:44px}.dpad .right{left:88px;top:44px}.actions{position:absolute;right:19px;bottom:30px;width:132px;height:105px;pointer-events:auto}.action{border-radius:50%;display:flex;flex-direction:column;align-items:center;justify-content:center;width:60px;height:60px;font-size:22px}.action small{font:700 7px 'DM Sans';letter-spacing:1px;margin-top:1px}.action.attack{right:0;bottom:0;background:#89513b9c}.action.dash{left:0;bottom:10px;background:#526c679c}.dpad button:active,.action:active{background:#d6ad66a8}.screen-content{margin:0 auto;width:90%;transform:translateY(-22px)}.screen h1{font-size:clamp(52px,15vw,75px)}.screen h2{font-size:clamp(36px,10vw,52px)}.screen-copy{font-size:11px}.screen-controls{font-size:7px}.screen-footer{bottom:13px;font-size:6px;letter-spacing:1.6px}.sun-seal{width:36px;height:36px;font-size:20px;margin-bottom:12px}.screen-rule{margin:12px auto}.toast{top:24%;font-size:10px}}
@media(max-height:500px) and (min-width:701px){.screen-content{transform:scale(.82);transform-origin:center}.hud{top:74px}.hero-card,.objective{height:64px}.topbar{height:55px}.hint{bottom:12px}}

(() => {
const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d');
const $=s=>document.querySelector(s), hpFill=$('#healthFill'),hpText=$('#hpText'),peachTrack=$('#peachTrack'),questText=$('#questText'),bossBar=$('#bossBar'),bossFill=$('#bossFill'),bossHpText=$('#bossHpText'),toast=$('#toast');
let W=innerWidth,H=innerHeight,DPR=1,playing=false,ended=false,muted=true,audio=null,last=0,toastTimer,cam={x:0,y:0},elapsed=0,shake=0;
const world={w:1900,h:1400},keys={},peaches=[],enemies=[],particles=[],decor=[];
let collected=0,player,boss,attackCd=0,dashCd=0,invuln=0,attackTimer=0,toastQueue=[];
function resize(){let r=canvas.getBoundingClientRect();DPR=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(r.width*DPR);canvas.height=Math.round(r.height*DPR);W=r.width;H=r.height;ctx.setTransform(DPR,0,0,DPR,0,0)}addEventListener('resize',resize);resize();
function rand(a,b){return a+Math.random()*(b-a)}
function seedWorld(){peaches.length=0;enemies.length=0;decor.length=0;particles.length=0;let points=[[280,270],[540,480],[920,310],[1380,430],[480,990],[1060,940],[1500,1000]];points.forEach((p,i)=>peaches.push({x:p[0],y:p[1],taken:i>=5,pulse:rand(0,7)}));for(let i=0;i<36;i++){let x=rand(65,world.w-65),y=rand(100,world.h-60);if(Math.hypot(x-950,y-700)<155)continue;decor.push({x,y,type:Math.random()<.54?'tree':'stone',s:rand(.65,1.3),seed:i})}player={x:950,y:850,faceX:0,faceY:-1,hp:100,maxHp:100,attack:0,dash:0,hit:0};boss={x:950,y:206,hp:100,maxHp:100,active:false,attack:0,phase:0,hit:0};collected=0;attackCd=dashCd=invuln=attackTimer=0;updateHUD()}
function updateHUD(){hpFill.style.width=`${Math.max(0,player.hp)}%`;hpText.textContent=Math.max(0,Math.ceil(player.hp));peachTrack.innerHTML='';for(let i=0;i<5;i++){let e=document.createElement('i');e.className='peach-slot'+(i<collected?' filled':'');peachTrack.append(e)}if(collected<5)questText.textContent=`Gather the celestial peaches  ${collected}/5`;else questText.textContent=boss.hp>0?'Defeat the Iron Bull':'The mountain is yours'}
function notify(text){toast.textContent=text;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),2100)}
function start(){seedWorld();playing=true;ended=false;$('#startScreen').classList.add('hidden');$('#endScreen').classList.add('hidden');bossBar.classList.remove('show');$('#hint').style.opacity=1;last=performance.now();audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume?.()}
$('#startBtn').onclick=start;$('#restartBtn').onclick=start;
function end(win){playing=false;ended=true;bossBar.classList.remove('show');$('#endTitle').innerHTML=win?'A LEGEND<br><span>RECLAIMED</span>':'THE MOUNTAIN<br><span>CLAIMS YOU</span>';$('#endEyebrow').textContent=win?'THE HEAVENS SING':'NOT THIS TIME, GREAT SAGE';$('#endCopy').textContent=win?'The peaches are yours. The mountain remembers.':'Even the Monkey King needs another try.';$('#endSeal').textContent=win?'✦':'☯';$('#endScreen').classList.remove('hidden')}
function sound(freq=360,dur=.08,type='sine',vol=.035){if(muted||!audio)return;let o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(vol,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+dur)}$('#soundBtn').onclick=()=>{muted=!muted;$('#soundBtn').innerHTML=muted?'♪ <span>SOUND OFF</span>':'♫ <span>SOUND ON</span>';if(!muted){audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume()}};
addEventListener('keydown',e=>{let k=e.key.toLowerCase();keys[k]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(!playing)return;if(k===' '||k==='j')attack();if(k==='shift'||k==='k')dash()});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
document.querySelectorAll('.dpad button').forEach(b=>{let k=b.dataset.key.toLowerCase();b.onpointerdown=e=>{e.preventDefault();keys[k]=true;b.setPointerCapture(e.pointerId)};['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>keys[k]=false))});document.querySelectorAll('[data-action]').forEach(b=>b.onpointerdown=e=>{e.preventDefault();if(b.dataset.action==='attack')attack();else dash()});
function attack(){if(!playing||attackCd>0)return;attackCd=.36;player.attack=.25;attackTimer=.2;sound(190,.11,'triangle',.05);particles.push({x:player.x+player.faceX*35,y:player.y+player.faceY*35,life:.2,max:.2,type:'slash',a:Math.atan2(player.faceY,player.faceX)});for(let e of [...enemies,boss]){if(e.hp<=0||e===boss&&!boss.active)continue;let dx=e.x-player.x,dy=e.y-player.y,dist=Math.hypot(dx,dy),dot=(dx*player.faceX+dy*player.faceY)/(dist||1);if(dist<95&&dot>-.3){e.hp-=e===boss?13:45;e.hit=.18;shake=5;for(let i=0;i<8;i++)particles.push({x:e.x,y:e.y-18,vx:rand(-100,100),vy:rand(-140,20),life:rand(.2,.48),max:.48,type:'spark',color:'#f9ce79'});sound(120,.12,'square',.025);if(e.hp<=0&&e!==boss){e.dead=true;sound(470,.18,'sine',.04)}if(e===boss&&e.hp<=0){e.hp=0;bossBar.classList.remove('show');updateHUD();setTimeout(()=>end(true),900)}}}}
function dash(){if(!playing||dashCd>0)return;dashCd=1.1;player.dash=.22;invuln=.32;let dx=player.faceX,dy=player.faceY;if(!dx&&!dy)dy=-1;player.x=Math.max(45,Math.min(world.w-45,player.x+dx*145));player.y=Math.max(95,Math.min(world.h-45,player.y+dy*145));for(let i=0;i<10;i++)particles.push({x:player.x-dx*i*11,y:player.y-dy*i*11,vx:rand(-12,12),vy:rand(-12,12),life:.42,max:.42,type:'cloud'});sound(520,.16,'sine',.035)}
function hurt(dmg){if(invuln>0)return;player.hp=Math.max(0,player.hp-dmg);invuln=.8;shake=8;updateHUD();sound(90,.22,'sawtooth',.04);for(let i=0;i<9;i++)particles.push({x:player.x,y:player.y-15,vx:rand(-110,110),vy:rand(-100,10),life:.35,max:.35,type:'spark',color:'#ec765e'});if(player.hp<=0)end(false)}
function spawnEnemy(){if(enemies.filter(e=>!e.dead).length>=4)return;let a=rand(0,Math.PI*2),x=950+Math.cos(a)*rand(300,520),y=700+Math.sin(a)*rand(240,390);x=Math.max(65,Math.min(world.w-65,x));y=Math.max(100,Math.min(world.h-55,y));enemies.push({x,y,hp:70,maxHp:70,speed:rand(49,67),attack:rand(.3,1),hit:0,dead:false,phase:rand(0,6),type:Math.random()<.3?'archer':'soldier'})}
function update(dt){elapsed+=dt;attackCd=Math.max(0,attackCd-dt);dashCd=Math.max(0,dashCd-dt);invuln=Math.max(0,invuln-dt);player.attack=Math.max(0,player.attack-dt);player.dash=Math.max(0,player.dash-dt);let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0),len=Math.hypot(dx,dy);if(len){dx/=len;dy/=len;player.faceX=dx;player.faceY=dy;player.x+=dx*215*dt;player.y+=dy*215*dt}player.x=Math.max(38,Math.min(world.w-38,player.x));player.y=Math.max(85,Math.min(world.h-40,player.y));
if(collected>=5&&!boss.active&&boss.hp>0){boss.active=true;bossBar.classList.add('show');notify('The Iron Bull awakens!');updateHUD()}if(collected<5&&Math.random()<dt*.5&&enemies.length<3)spawnEnemy();
for(let p of peaches){p.pulse+=dt*2;if(!p.taken&&Math.hypot(p.x-player.x,p.y-player.y)<45){p.taken=true;collected++;player.hp=Math.min(100,player.hp+12);updateHUD();notify(collected===5?'The Iron Bull stirs beneath the shrine...':'Celestial peach reclaimed');sound(660,.25,'sine',.045);for(let i=0;i<12;i++)particles.push({x:p.x,y:p.y,vx:rand(-90,90),vy:rand(-130,20),life:.7,max:.7,type:'spark',color:'#ffdb78'})}}
for(let e of enemies){if(e.dead)continue;e.hit=Math.max(0,e.hit-dt);e.attack-=dt;let ex=player.x-e.x,ey=player.y-e.y,d=Math.hypot(ex,ey)||1;if(d>37){e.x+=ex/d*e.speed*dt;e.y+=ey/d*e.speed*dt}if(d<48&&e.attack<=0){e.attack=e.type==='archer'?1.5:1.05;if(e.type==='archer'&&d>100){particles.push({x:e.x,y:e.y-20,vx:ex/d*230,vy:ey/d*230,life:1.3,max:1.3,type:'bolt'})}else hurt(8)}}
for(let p of particles){p.life-=dt;if(p.type==='bolt'){p.x+=p.vx*dt;p.y+=p.vy*dt;if(Math.hypot(p.x-player.x,p.y-player.y)<22){p.life=0;hurt(10)}}else if(p.vx!==undefined){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=140*dt}}
for(let i=particles.length-1;i>=0;i--)if(particles[i].life<=0)particles.splice(i,1);for(let i=enemies.length-1;i>=0;i--)if(enemies[i].dead)enemies.splice(i,1);
if(boss.active&&boss.hp>0){boss.phase+=dt;boss.hit=Math.max(0,boss.hit-dt);boss.attack-=dt;let d=Math.hypot(player.x-boss.x,player.y-boss.y),ex=player.x-boss.x,ey=player.y-boss.y;if(d>86){boss.x+=ex/d*53*dt;boss.y+=ey/d*53*dt}if(boss.attack<=0){boss.attack=1.55;if(d<125){hurt(17);for(let i=0;i<12;i++)particles.push({x:boss.x,y:boss.y,vx:rand(-180,180),vy:rand(-180,80),life:.45,max:.45,type:'spark',color:'#ff875d'})}else{for(let i=-1;i<=1;i++){let a=Math.atan2(ey,ex)+i*.24;particles.push({x:boss.x,y:boss.y-5,vx:Math.cos(a)*220,vy:Math.sin(a)*220,life:1.5,max:1.5,type:'bolt',color:'#ff8359'})}}}bossFill.style.width=(boss.hp/boss.maxHp*100)+'%';bossHpText.textContent=Math.ceil(boss.hp)+'%'}
cam.x=Math.max(0,Math.min(world.w-W,player.x-W/2));cam.y=Math.max(0,Math.min(world.h-H,player.y-H/2));shake=Math.max(0,shake-dt*20)}
function rounded(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r)}
function drawGround(){let g=ctx.createLinearGradient(0,0,W,H);g.addColorStop(0,'#42645a');g.addColorStop(.52,'#52705d');g.addColorStop(1,'#344e48');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
// painterly terrain washes
for(let i=0;i<32;i++){let x=((i*317+83)%world.w)-cam.x,y=((i*197+280)%world.h)-cam.y;if(x<-180||x>W+180||y<-150||y>H+150)continue;ctx.fillStyle=i%3===0?'#99a7780c':i%3===1?'#152c2c0c':'#d7c58d0a';ctx.beginPath();ctx.ellipse(x,y,rand(45,120),rand(22,65),i*.4,0,Math.PI*2);ctx.fill()}
// mountain ridge silhouettes
for(let layer=0;layer<3;layer++){let base=-cam.y+layer*42;ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(0,base+125);for(let x=0;x<=W+40;x+=40){let y=base+95+Math.sin((x+cam.x*.12+layer*130)/145)*45+Math.sin(x/61+layer)*18;ctx.lineTo(x,y)}ctx.lineTo(W,0);ctx.closePath();ctx.fillStyle=['#a6b0a04a','#506d6244','#314e4944'][layer];ctx.fill()}
// meandering stone path
ctx.lineCap='round';ctx.beginPath();for(let y=0;y<=world.h;y+=20){let x=950+Math.sin(y/170)*85+Math.sin(y/320)*65;if(y===0)ctx.moveTo(x-cam.x,y-cam.y);else ctx.lineTo(x-cam.x,y-cam.y)}ctx.strokeStyle='#c9b88c22';ctx.lineWidth=115;ctx.stroke();ctx.strokeStyle='#ddd0ac16';ctx.lineWidth=88;ctx.stroke();
// stream on right
ctx.beginPath();for(let y=0;y<=world.h;y+=20){let x=1570+Math.sin(y/130)*50;if(y===0)ctx.moveTo(x-cam.x,y-cam.y);else ctx.lineTo(x-cam.x,y-cam.y)}ctx.strokeStyle='#7fa79a77';ctx.lineWidth=55;ctx.stroke();ctx.strokeStyle='#aed1c344';ctx.lineWidth=39;ctx.stroke();for(let j=0;j<20;j++){let y=((j*73+elapsed*25)%world.h)-cam.y,x=1570+Math.sin((y+cam.y)/130)*50-cam.x;ctx.strokeStyle='#d5e0bb36';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x-12,y);ctx.lineTo(x+10,y-2);ctx.stroke()}
// ground flecks deterministic
